        checks=[
            Check("slope", "isTRUE(all.equal(as.numeric(user$slope), as.numeric(ref$slope), tolerance = 1e-8))", hint="Slope differs: check the train rows 1:78."),
            Check("test_mae", "isTRUE(all.equal(as.numeric(user$test_mae), as.numeric(ref$test_mae), tolerance = 1e-8))", hint="Test MAE differs: evaluate on rows 79 onwards."),
        ],
        visible_tests=["Slope and test MAE match the reference"],
